    const dialog = document.getElementById('delete-dialog');
    const trigger = document.querySelector('.trigger');
    const closeBtn = dialog.querySelector('[data-close]');
    const confirmBtn = dialog.querySelector('[data-confirm]');

    if (!dialog || !trigger) return;

    trigger.addEventListener('click', () => {
        dialog.showModal();
        // Move focus to the "Cancel" button instead of "Delete" to prevent accidental confirmation
        closeBtn.focus();
    });

    closeBtn.addEventListener('click', () => {
        dialog.close('cancel');
    });

    confirmBtn.addEventListener('click', () => {
        // Here you would normally handle the actual deletion logic
        console.log('Image deleted');
        dialog.close('delete');

        // For demonstration, let's just hide the image container
        const container = document.querySelector('.image-container');
        const status = document.getElementById('status');
        if (container) {
            container.innerHTML = '<p>Image has been deleted from your library.</p>';
            if (status) {
                status.textContent = 'Image has been deleted from your library.';
            }
        }
    });

    // Close on backdrop click (optional but common)
    dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (
            rect.top <= event.clientY &&
            event.clientY <= rect.top + rect.height &&
            rect.left <= event.clientX &&
            event.clientX <= rect.left + rect.width
        );
        if (!isInDialog) {
            dialog.close();
        }
    });
});
