const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    // Load the local index.html
    const filePath = 'file://' + path.resolve('index.html');
    await page.goto(filePath);

    // Inject axe-core
    await page.addScriptTag({ path: '/tmp/axe.min.js' });

    // Run axe on the initial state (dialog closed)
    const resultsClosed = await page.evaluate(async () => {
        return await window.axe.run();
    });

    console.log('--- Initial State (Dialog Closed) ---');
    printResults(resultsClosed);

    // Open the dialog
    await page.click('.trigger');

    // Run axe on the open state
    const resultsOpen = await page.evaluate(async () => {
        return await window.axe.run();
    });

    console.log('\n--- Dialog Open State ---');
    printResults(resultsOpen);

    await browser.close();

    const hasViolations = resultsClosed.violations.some(v => !v.tags.includes('best-practice')) || 
                          resultsOpen.violations.some(v => !v.tags.includes('best-practice'));

    process.exit(hasViolations ? 1 : 0);
})();

function printResults(results) {
    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }, null, 2));
}

